#!/usr/bin/env bash
# TSP-only PowerVR gl4es fork: actual proxy-renderbuffer lifetime fix + toggleable diagnostics.
# NEVER edits /root/gl4es-tsp or /root/gl4es-tsps. NEVER overwrites production device lib/libGL.so.1.

if [[ "${BASH_SOURCE[0]}" != "$0" ]]; then
    echo "ERROR: run this script; do not source it."
    return 1
fi
set -Eeuo pipefail

HOST="${1:-${TSP_HOST:-root@192.168.1.21}}"
CONTAINER="openmw_builder"
BASE="/root/gl4es-tsp"
FORK="/root/gl4es-tsp-pvr-lifetime-v1"
BUILD_SRC="/root/rebuild_gl4es_tsps_o3.sh"
BUILD_FORK="/root/rebuild_gl4es_tsp_pvr_lifetime_v1.sh"
ROOT="/mnt/mmc/ports/openmw"
PORTS="/mnt/mmc/ROMS/Ports"
DL="$HOME/Downloads"
STAMP="$(date +%Y%m%d-%H%M%S)"
LOCAL_GL="$DL/libGL.so.1-tsp-pvr-lifetime-v1"
LOCAL_LAUNCHER="$DL/Morrowind-TSP-PVR-LIFETIME-DIAG-V11.sh"
SOCK="/tmp/tsp-pvr-life-$$"
EXPECTED_PROD_SHA="98794823e6df485fd90c53bdbdf5830e0118eda212b0d4b141562bb692e090bb"
mkdir -p "$DL"

cleanup(){ [ -S "$SOCK" ] || [ -e "$SOCK" ] && ssh -S "$SOCK" -O exit "$HOST" >/dev/null 2>&1 || true; }
trap cleanup EXIT
fail(){ rc="${2:-1}"; echo; echo "PATCH STOPPED: $1"; echo "return_code=$rc"; echo "Your VM terminal remains open."; exit "$rc"; }

echo "============================================================"
echo "TSP PVR NATIVE LIFETIME V3"
echo "============================================================"
echo "Current TSP source (READ ONLY):             $BASE"
echo "TSPS source (also untouched):               /root/gl4es-tsps"
echo "New TSP source fork:                    $FORK"
echo "Device:                                 $HOST"
echo

echo "[0/10] SSH/PASSWORD PRECHECK FIRST"
if ! ssh -M -S "$SOCK" -o ControlMaster=yes -o ControlPersist=yes -o ConnectTimeout=6 "$HOST" true; then
    fail "Cannot reach/authenticate to $HOST. Nothing was changed." 10
fi
echo "SSH PRECHECK: PASS"

command -v docker >/dev/null 2>&1 || fail "docker missing" 11
docker inspect "$CONTAINER" >/dev/null 2>&1 || fail "container missing: $CONTAINER" 12

echo "[1/10] VERIFYING CURRENT PRODUCTION DEVICE LIBGL"
PROD_SHA="$(ssh -S "$SOCK" -o BatchMode=yes "$HOST" "sha256sum '$ROOT/lib/libGL.so.1' 2>/dev/null | cut -c1-64")"
[ -n "$PROD_SHA" ] || fail "Could not hash production libGL" 13
echo "production libGL=$PROD_SHA"
[ "$PROD_SHA" = "$EXPECTED_PROD_SHA" ] || fail "Production libGL differs from the recent texlife-v2 binary; refusing an uncertain fork." 14

echo "[2/10] BACKING UP RELEVANT SOURCE STATE"
docker exec -i "$CONTAINER" bash -s -- "$STAMP" <<'DOCKER_BACKUP'
set -euo pipefail
STAMP="$1"
BASE="/root/gl4es-tsp"
TSPS="/root/gl4es-tsps"
B="/root/tsp_patch_backups/pvr-lifetime-pre-v2-$STAMP"
mkdir -p "$B"

[ -d "$BASE" ] || { echo "ERROR missing current TSP source: $BASE"; exit 20; }
[ -d "$TSPS" ] || { echo "ERROR missing TSPS source: $TSPS"; exit 21; }
[ -f /root/rebuild_gl4es_tsps_o3.sh ] || { echo "ERROR missing rebuild script"; exit 22; }

grep -q 'TSP_TEXLIFE_V2' "$BASE/src/gl/texture_params.c" || {
    echo "ERROR: /root/gl4es-tsp is not the recent TSP_TEXLIFE_V2 source tree"
    exit 23
}

cp -p /root/rebuild_gl4es_tsps_o3.sh "$B/rebuild_gl4es_tsps_o3.sh"

for f in "$BASE/src/gl/framebuffers.c" "$BASE/src/gl/texture_params.c" "$BASE/src/gl/texture.c" "$BASE/src/gl/texture.h"; do
    cp -p "$f" "$B/tsp-$(basename "$f").before"
    sha256sum "$f" >> "$B/tsp-source-sha256.before"
done

for f in "$TSPS/src/gl/framebuffers.c" "$TSPS/src/gl/texture_params.c" "$TSPS/src/gl/texture.c" "$TSPS/src/gl/texture.h"; do
    sha256sum "$f" >> "$B/tsps-source-sha256.untouched"
done

git -C "$BASE" status --short --branch > "$B/tsp-git-status.before.txt" 2>&1 || true
git -C "$BASE" diff --no-ext-diff --full-index > "$B/tsp-git-diff.before.txt" 2>&1 || true
git -C "$TSPS" status --short --branch > "$B/tsps-git-status.before.txt" 2>&1 || true
git -C "$TSPS" diff --no-ext-diff --full-index > "$B/tsps-git-diff.before.txt" 2>&1 || true

echo "source_backup=$B"
DOCKER_BACKUP

ssh -S "$SOCK" -o BatchMode=yes "$HOST" 'sh -s' > "$DL/tsp-pvr-lifetime-device-before-$STAMP.txt" <<'REMOTE_BACKUP'
ROOT="/mnt/mmc/ports/openmw"; PORTS="/mnt/mmc/ROMS/Ports"
echo "date=$(date)"
sha256sum "$ROOT/lib/libGL.so.1" 2>/dev/null || true
for f in "$PORTS"/Morrowind-*.sh; do [ -f "$f" ] && sha256sum "$f" 2>/dev/null || true; done
REMOTE_BACKUP

echo "[3/10] CREATING NEW SOURCE TREE BEFORE EDITING"
docker exec -i "$CONTAINER" bash -s -- "$BASE" "$FORK" <<'DOCKER_FORK'
set -euo pipefail
BASE="$1"; FORK="$2"
[ -d "$BASE" ] || { echo "ERROR: base tree missing: $BASE"; exit 30; }

if [ -e "$FORK" ]; then
    OLD="${FORK}.previous-$(date +%Y%m%d-%H%M%S)"
    mv "$FORK" "$OLD"
    echo "preserved_previous_fork=$OLD"
fi

mkdir -p "$FORK"

# Fresh SOURCE clone only. Do not copy the old build cache or lib output because
# those contain absolute paths to the original tree.
(
    cd "$BASE"
    tar -cf -         --exclude='./build-tsps-o3'         --exclude='./build-*'         --exclude='./lib'         .
) | (
    cd "$FORK"
    tar -xf -
)

[ -f "$FORK/src/gl/framebuffers.c" ] || {
    echo "ERROR: fork clone missing src/gl/framebuffers.c"
    find "$FORK" -maxdepth 3 -type d -print 2>/dev/null | head -80
    exit 31
}

[ -f "$FORK/src/gl/texture_params.c" ] || {
    echo "ERROR: fork clone missing src/gl/texture_params.c"
    exit 32
}

[ "$(readlink -f "$BASE")" != "$(readlink -f "$FORK")" ] || {
    echo "ERROR: fork path aliases base"
    exit 33
}

cmp -s "$BASE/src/gl/framebuffers.c" "$FORK/src/gl/framebuffers.c" || {
    echo "ERROR: framebuffers.c differs before patch"
    exit 34
}

cmp -s "$BASE/src/gl/texture_params.c" "$FORK/src/gl/texture_params.c" || {
    echo "ERROR: texture_params.c differs before patch"
    exit 35
}

grep -q 'TSP_TEXLIFE_V2' "$FORK/src/gl/texture_params.c" || {
    echo "ERROR: fork lost TSP_TEXLIFE_V2 before patching"
    exit 36
}

echo "fork_created=$FORK"
echo "fork_framebuffers=$(sha256sum "$FORK/src/gl/framebuffers.c" | cut -c1-64)"
echo "fork_texture_params=$(sha256sum "$FORK/src/gl/texture_params.c" | cut -c1-64)"
DOCKER_FORK

echo "[4/10] PATCHING ONLY THE NEW TSP FORK"
docker exec -i "$CONTAINER" python3 - <<'PY_PATCH'
from pathlib import Path
BASE=Path('/root/gl4es-tsp')
FORK=Path('/root/gl4es-tsp-pvr-lifetime-v1')
FB=FORK/'src/gl/framebuffers.c'
TP=FORK/'src/gl/texture_params.c'

def rep1(s,old,new,label):
    n=s.count(old)
    if n!=1: raise SystemExit(f'ERROR {label}: expected 1 anchor, found {n}')
    return s.replace(old,new,1)

s=FB.read_text()
if 'TSP_PVR_RB_LIFETIME_FIX_V1' not in s:
    anchor='/* TSP_BINDSYNC_20260816 */'
    helper=r'''/* TSP_NATIVE_LIFE_DIAG_V1 -------------------------------------------------
 * Native GLES lifetime accounting. Dormant unless LIBGL_TSP_NATIVE_LIFE=1.
 * With diagnostics OFF: no files, no sysfs/proc reads, no glGet probes and no
 * per-draw work. Calls exist only on resource create/delete/storage paths.
 */
typedef struct { GLuint id; unsigned long long bytes; int used; } tsp_native_rb_rec_t;
#define TSP_NATIVE_RB_MAX 2048
static tsp_native_rb_rec_t tsp_native_rb[TSP_NATIVE_RB_MAX];
static unsigned long tsp_native_fbo_gen=0, tsp_native_fbo_del=0;
static unsigned long tsp_native_rb_gen=0, tsp_native_rb_del=0;
static unsigned long tsp_native_tex_gen=0, tsp_native_tex_del=0;
static unsigned long long tsp_native_rb_live_bytes=0;
static unsigned long tsp_native_seq=0;

static int tsp_native_life_on(void) {
    static int chk=0,on=0;
    if(!chk){const char*e=getenv("LIBGL_TSP_NATIVE_LIFE");on=(e&&e[0]=='1');chk=1;}
    return on;
}
static FILE* tsp_native_life_file(void) {
    static int chk=0; static FILE* f=NULL;
    if(!tsp_native_life_on()) return NULL;
    if(!chk){
        const char*p=getenv("LIBGL_TSP_NATIVE_LIFE_PATH"); chk=1;
        if(p&&p[0]){f=fopen(p,"a");if(f){fprintf(f,"# TSP_NATIVE_LIFE_DIAG_V1 seq event fields\n");fflush(f);}}
    }
    return f;
}
static void tsp_native_log(const char*fmt,...) {
    FILE*f=tsp_native_life_file(); if(!f)return;
    unsigned long seq=__sync_add_and_fetch(&tsp_native_seq,1);
    fprintf(f,"seq=%lu ",seq);
    va_list ap;va_start(ap,fmt);vfprintf(f,fmt,ap);va_end(ap);fputc('\n',f);fflush(f);
}
static unsigned long long tsp_native_rb_estimate(GLenum fmt,GLsizei w,GLsizei h) {
    unsigned long long bpp=4;
    if(fmt==GL_STENCIL_INDEX8)bpp=1;
    else if(fmt==GL_DEPTH_COMPONENT16||fmt==GL_RGB565_OES||fmt==GL_RGBA4_OES)bpp=2;
    return (unsigned long long)w*(unsigned long long)h*bpp;
}
static tsp_native_rb_rec_t* tsp_native_rb_slot(GLuint id,int create) {
    tsp_native_rb_rec_t*empty=NULL;if(!id)return NULL;
    for(int i=0;i<TSP_NATIVE_RB_MAX;i++){
        if(tsp_native_rb[i].used&&tsp_native_rb[i].id==id)return &tsp_native_rb[i];
        if(!tsp_native_rb[i].used&&!empty)empty=&tsp_native_rb[i];
    }
    if(create&&empty){empty->used=1;empty->id=id;empty->bytes=0;return empty;}
    return NULL;
}
static void tsp_native_fbo_generated(GLuint id){if(!tsp_native_life_on()||!id)return;++tsp_native_fbo_gen;tsp_native_log("GEN_FBO id=%u gen=%lu del=%lu live=%ld",id,tsp_native_fbo_gen,tsp_native_fbo_del,(long)tsp_native_fbo_gen-(long)tsp_native_fbo_del);}
static void tsp_native_fbo_deleted(GLuint id){if(!tsp_native_life_on()||!id)return;++tsp_native_fbo_del;tsp_native_log("DEL_FBO id=%u gen=%lu del=%lu live=%ld",id,tsp_native_fbo_gen,tsp_native_fbo_del,(long)tsp_native_fbo_gen-(long)tsp_native_fbo_del);}
static void tsp_native_rb_generated(GLuint id,const char*owner){if(!tsp_native_life_on()||!id)return;++tsp_native_rb_gen;(void)tsp_native_rb_slot(id,1);tsp_native_log("GEN_RB id=%u owner=%s gen=%lu del=%lu live=%ld bytes=%llu",id,owner?owner:"?",tsp_native_rb_gen,tsp_native_rb_del,(long)tsp_native_rb_gen-(long)tsp_native_rb_del,tsp_native_rb_live_bytes);}
static void tsp_native_rb_deleted(GLuint id,const char*owner){
    if(!tsp_native_life_on()||!id)return;tsp_native_rb_rec_t*r=tsp_native_rb_slot(id,0);
    if(r){if(tsp_native_rb_live_bytes>=r->bytes)tsp_native_rb_live_bytes-=r->bytes;else tsp_native_rb_live_bytes=0;r->used=0;r->id=0;r->bytes=0;}
    ++tsp_native_rb_del;tsp_native_log("DEL_RB id=%u owner=%s gen=%lu del=%lu live=%ld bytes=%llu",id,owner?owner:"?",tsp_native_rb_gen,tsp_native_rb_del,(long)tsp_native_rb_gen-(long)tsp_native_rb_del,tsp_native_rb_live_bytes);
}
static void tsp_native_rb_storage(GLuint id,GLenum fmt,GLsizei w,GLsizei h,const char*owner){
    if(!tsp_native_life_on()||!id)return;tsp_native_rb_rec_t*r=tsp_native_rb_slot(id,1);unsigned long long b=tsp_native_rb_estimate(fmt,w,h);
    if(r){if(tsp_native_rb_live_bytes>=r->bytes)tsp_native_rb_live_bytes-=r->bytes;else tsp_native_rb_live_bytes=0;r->bytes=b;tsp_native_rb_live_bytes+=b;}
    tsp_native_log("RB_STORAGE id=%u owner=%s fmt=0x%x size=%dx%d est=%llu live_bytes=%llu",id,owner?owner:"?",fmt,w,h,b,tsp_native_rb_live_bytes);
}
void tsp_native_life_texture_generated(GLuint id){if(!tsp_native_life_on()||!id)return;++tsp_native_tex_gen;tsp_native_log("GEN_TEX gl=%u gen=%lu del=%lu live=%ld",id,tsp_native_tex_gen,tsp_native_tex_del,(long)tsp_native_tex_gen-(long)tsp_native_tex_del);}
void tsp_native_life_texture_deleted(GLuint id){if(!tsp_native_life_on()||!id)return;++tsp_native_tex_del;tsp_native_log("DEL_TEX gl=%u gen=%lu del=%lu live=%ld",id,tsp_native_tex_gen,tsp_native_tex_del,(long)tsp_native_tex_gen-(long)tsp_native_tex_del);}

/* TSP_PVR_RB_LIFETIME_FIX_V1
 * gl4es proxy depth/stencil renderbuffers belonged to a texture. Old
 * glDeleteFramebuffers() zeroed renderdepth/renderstencil before deleting the
 * native RB, making the later texture destructor unable to free it.
 */
static void tsp_pvr_delete_proxy_rb(GLuint*id,const char*owner){
    if(!id||!*id)return;GLuint doomed=*id;*id=0;tsp_native_rb_deleted(doomed,owner);gl4es_glDeleteRenderbuffers(1,&doomed);
}
/* ---------------------------------------------------------------------- */

'''
    s=rep1(s,anchor,helper+anchor,'helper')
    s=rep1(s,'        gles_glGenFramebuffers(n-m, ids+m);\n','        gles_glGenFramebuffers(n-m, ids+m);\n        for (int tsp_i=m; tsp_i<n; ++tsp_i) tsp_native_fbo_generated(ids[tsp_i]);\n','fbo gen')
    s=rep1(s,'''                            if(tex) {
                                tex->binded_fbo = 0;
                                tex->binded_attachment = 0;
                                tex->renderdepth = 0;
                            }
''','''                            if(tex) {
                                tex->binded_fbo = 0;
                                tex->binded_attachment = 0;
                                tsp_pvr_delete_proxy_rb(&tex->renderdepth, "fbo-depth-proxy");
                            }
''','depth proxy')
    s=rep1(s,'''                            if(tex) {
                                tex->binded_fbo = 0;
                                tex->binded_attachment = 0;
                                tex->renderstencil = 0;
                            }
''','''                            if(tex) {
                                tex->binded_fbo = 0;
                                tex->binded_attachment = 0;
                                tsp_pvr_delete_proxy_rb(&tex->renderstencil, "fbo-stencil-proxy");
                            }
''','stencil proxy')
    s=rep1(s,'        gles_glDeleteFramebuffers(n, framebuffers);\n','        for (int tsp_i=0; tsp_i<n; ++tsp_i) tsp_native_fbo_deleted(framebuffers[tsp_i]);\n        gles_glDeleteFramebuffers(n, framebuffers);\n','fbo delete')
    s=rep1(s,'    gles_glGenRenderbuffers(n, renderbuffers);\n    // track the renderbuffers...\n','    gles_glGenRenderbuffers(n, renderbuffers);\n    for (int tsp_i=0; tsp_i<n; ++tsp_i) tsp_native_rb_generated(renderbuffers[tsp_i], "glGenRenderbuffers");\n    // track the renderbuffers...\n','rb gen')
    s=rep1(s,'''                        if(rend->secondarybuffer)
                            gles_glDeleteRenderbuffers(1, &rend->secondarybuffer);
''','''                        if(rend->secondarybuffer) {
                            tsp_native_rb_deleted(rend->secondarybuffer, "secondarybuffer-delete");
                            gles_glDeleteRenderbuffers(1, &rend->secondarybuffer);
                        }
''','secondary delete')
    s=rep1(s,'    errorGL();\n    gles_glDeleteRenderbuffers(n, renderbuffers);\n}\n\nvoid APIENTRY_GL4ES gl4es_glRenderbufferStorage','    errorGL();\n    for (int tsp_i=0; tsp_i<n; ++tsp_i) tsp_native_rb_deleted(renderbuffers[tsp_i], "glDeleteRenderbuffers");\n    gles_glDeleteRenderbuffers(n, renderbuffers);\n}\n\nvoid APIENTRY_GL4ES gl4es_glRenderbufferStorage','rb delete')
    s=rep1(s,'            gles_glGenRenderbuffers(1, &rend->secondarybuffer);\n','            gles_glGenRenderbuffers(1, &rend->secondarybuffer);\n            tsp_native_rb_generated(rend->secondarybuffer, "secondarybuffer-create");\n','secondary gen')
    s=rep1(s,'            gles_glRenderbufferStorage(target, GL_STENCIL_INDEX8, width, height);\n            gles_glBindRenderbuffer(GL_RENDERBUFFER, current_rb);\n','            gles_glRenderbufferStorage(target, GL_STENCIL_INDEX8, width, height);\n            tsp_native_rb_storage(rend->secondarybuffer, GL_STENCIL_INDEX8, width, height, "secondarybuffer-storage");\n            gles_glBindRenderbuffer(GL_RENDERBUFFER, current_rb);\n','secondary storage')
    s=rep1(s,'            gles_glDeleteRenderbuffers(1, &rend->secondarybuffer);\n            rend->secondarybuffer = 0;\n','            tsp_native_rb_deleted(rend->secondarybuffer, "secondarybuffer-mode-change");\n            gles_glDeleteRenderbuffers(1, &rend->secondarybuffer);\n            rend->secondarybuffer = 0;\n','secondary mode delete')
    s=rep1(s,'    gles_glRenderbufferStorage(target, internalformat, width, height);\n    DBG(CheckGLError(1);)\n}\n','    gles_glRenderbufferStorage(target, internalformat, width, height);\n    tsp_native_rb_storage(rend->renderbuffer, internalformat, width, height, "primary-storage");\n    DBG(CheckGLError(1);)\n}\n','rb storage')
    FB.write_text(s)

t=TP.read_text()
if 'TSP_PVR_RB_LIFETIME_FIX_V1' not in t:
    anchor='KHASH_MAP_IMPL_INT(tex, gltexture_t *);'
    t=rep1(t,anchor,'/* TSP_NATIVE_LIFE_DIAG_V1 */\nvoid tsp_native_life_texture_generated(GLuint glname);\nvoid tsp_native_life_texture_deleted(GLuint glname);\n\n'+anchor,'decls')
    t=rep1(t,'''        if (texture)
            gles_glGenTextures(1, &tex->glname);
        else
''','''        if (texture) {
            gles_glGenTextures(1, &tex->glname);
            tsp_native_life_texture_generated(tex->glname);
        } else
''','tex gen')
    t=rep1(t,'''                gles_glDeleteTextures(1, &tex->glname);
                // check if renderbuffer where associeted
                if(tex->binded_fbo) {
                    if(tex->renderdepth)
                        gl4es_glDeleteRenderbuffers(1, &tex->renderdepth);
                    if(tex->renderstencil)
                        gl4es_glDeleteRenderbuffers(1, &tex->renderstencil);
                }
''','''                tsp_native_life_texture_deleted(tex->glname);
                gles_glDeleteTextures(1, &tex->glname);
                /* TSP_PVR_RB_LIFETIME_FIX_V1: proxy ownership belongs to
                   the texture, not to current binded_fbo state. */
                if(tex->renderdepth)
                    gl4es_glDeleteRenderbuffers(1, &tex->renderdepth);
                if(tex->renderstencil)
                    gl4es_glDeleteRenderbuffers(1, &tex->renderstencil);
''','tex proxy cleanup')
    a='        gles_glGenTextures(n-m, textures+m);\n'
    if a in t:
        t=rep1(t,a,'        gles_glGenTextures(n-m, textures+m);\n        for (int tsp_i=m; tsp_i<n; ++tsp_i) tsp_native_life_texture_generated(textures[tsp_i]);\n','bulk tex gen')
    TP.write_text(t)

for rel in ('src/gl/framebuffers.c','src/gl/texture_params.c'):
    if (BASE/rel).read_bytes()==(FORK/rel).read_bytes(): raise SystemExit('ERROR fork file unchanged: '+rel)
for p in (FB,TP):
    txt=p.read_text()
    for marker in ('TSP_PVR_RB_LIFETIME_FIX_V1','TSP_NATIVE_LIFE_DIAG_V1'):
        if marker not in txt: raise SystemExit(f'ERROR missing {marker} in {p}')
print('PASS: patched only new fork')
PY_PATCH

echo "[5/10] CLONING BUILD SCRIPT FOR NEW TREE"
docker exec -i "$CONTAINER" bash -s -- "$BUILD_SRC" "$BUILD_FORK" <<'DOCKER_BUILD_SCRIPT'
set -euo pipefail
SRC="$1"; DST="$2"
cp -p "$SRC" "$DST"
python3 - "$DST" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1]);s=p.read_text();old='/root/gl4es-tsps';new='/root/gl4es-tsp-pvr-lifetime-v1';n=s.count(old)
if n<1: raise SystemExit('ERROR no gl4es-tsps path in rebuild script')
p.write_text(s.replace(old,new));print('replaced_paths',n)
PY
chmod +x "$DST"
grep -q '/root/gl4es-tsp-pvr-lifetime-v1' "$DST"
if grep -q '/root/gl4es-tsps' "$DST"; then echo "ERROR old source path remains"; exit 40; fi
DOCKER_BUILD_SCRIPT

echo "[6/10] BUILDING NEW FORK WITH BASH"
docker exec "$CONTAINER" bash "$BUILD_FORK"
BUILT="$(docker exec -i "$CONTAINER" bash -s -- "$FORK" <<'DOCKER_FIND'
FORK="$1"
for f in "$FORK/lib/libGL.so.1" "$FORK/build-tsps-o3/lib/libGL.so.1" "$FORK/build-tsps-o3/libGL.so.1"; do [ -f "$f" ] && { echo "$f"; exit 0; }; done
find "$FORK" -maxdepth 5 -type f -name 'libGL.so.1' -print 2>/dev/null | head -n1
DOCKER_FIND
)"
[ -n "$BUILT" ] || fail "built libGL not found" 50
docker cp "$CONTAINER:$BUILT" "$LOCAL_GL"
chmod 0755 "$LOCAL_GL"
grep -a -q 'TSP_PVR_RB_LIFETIME_FIX_V1' "$LOCAL_GL" || fail "new marker missing from libGL" 51
grep -a -q 'TSP_NATIVE_LIFE_DIAG_V1' "$LOCAL_GL" || fail "diag marker missing from libGL" 52
NEW_SHA="$(sha256sum "$LOCAL_GL" | awk '{print $1}')"
[ "$NEW_SHA" != "$PROD_SHA" ] || fail "new libGL unexpectedly identical to production" 53
echo "new TSP libGL=$NEW_SHA"

echo "[7/10] EMITTING DEDICATED V11 LAUNCHER"
base64 -d > "$LOCAL_LAUNCHER" <<'V11_B64'

V11_B64
chmod 0755 "$LOCAL_LAUNCHER"
LAUNCH_SHA="$(sha256sum "$LOCAL_LAUNCHER" | awk '{print $1}')"
[ "$LAUNCH_SHA" = "e3b812829ddb259f5cce5b81a3eeb6dcdc16114ffe809079d9855d43d1f9413a" ] || fail "embedded V11 hash mismatch" 60
sh -n "$LOCAL_LAUNCHER"; bash -n "$LOCAL_LAUNCHER"

echo "[8/10] COPYING NEW SIDE-BY-SIDE FILES"
scp -q -o ControlPath="$SOCK" "$LOCAL_GL" "$HOST:/tmp/libGL.so.1-tsp-pvr-lifetime-v1"
scp -q -o ControlPath="$SOCK" "$LOCAL_LAUNCHER" "$HOST:/tmp/Morrowind-TSP-PVR-LIFETIME-DIAG-V11.sh"

echo "[9/10] INSTALLING TSP-ONLY SIDECAR; VERIFYING PRODUCTION UNCHANGED"
ssh -S "$SOCK" -o BatchMode=yes "$HOST" 'sh -s' -- "$NEW_SHA" "$LAUNCH_SHA" <<'REMOTE_INSTALL'
set -e
NEW_SHA="$1"; LAUNCH_SHA="$2"
ROOT="/mnt/mmc/ports/openmw"; PORTS="/mnt/mmc/ROMS/Ports"
PROD="$ROOT/lib/libGL.so.1"; SIDE_DIR="$ROOT/lib.tsp-pvr-lifetime-v1"; SIDE="$SIDE_DIR/libGL.so.1"; LAUNCH="$PORTS/Morrowind-TSP-PVR-LIFETIME-DIAG-V11.sh"
PROD_BEFORE="$(sha256sum "$PROD" | awk '{print $1}')"
STAMP="$(date +%Y%m%d-%H%M%S)"; BACK="$ROOT/tsp_patch_backups/pvr-native-lifetime-v2-$STAMP"; mkdir -p "$BACK"
[ -f "$SIDE" ] && cp -p "$SIDE" "$BACK/libGL-sidecar.before" || true
[ -f "$LAUNCH" ] && cp -p "$LAUNCH" "$BACK/launcher.before" || true
sha256sum "$PROD" > "$BACK/production-libGL.sha256"
mkdir -p "$SIDE_DIR"
install -m 0755 /tmp/libGL.so.1-tsp-pvr-lifetime-v1 "$SIDE"
install -m 0755 /tmp/Morrowind-TSP-PVR-LIFETIME-DIAG-V11.sh "$LAUNCH"
rm -f /tmp/libGL.so.1-tsp-pvr-lifetime-v1 /tmp/Morrowind-TSP-PVR-LIFETIME-DIAG-V11.sh
[ "$(sha256sum "$SIDE" | awk '{print $1}')" = "$NEW_SHA" ] || { echo "ERROR sidecar hash"; exit 70; }
[ "$(sha256sum "$LAUNCH" | awk '{print $1}')" = "$LAUNCH_SHA" ] || { echo "ERROR launcher hash"; exit 71; }
PROD_AFTER="$(sha256sum "$PROD" | awk '{print $1}')"
[ "$PROD_BEFORE" = "$PROD_AFTER" ] || { echo "ERROR production libGL changed"; exit 72; }
echo "PRODUCTION UNCHANGED:"; sha256sum "$PROD"
echo "TSP SIDECAR:"; sha256sum "$SIDE"
echo "V11 LAUNCHER:"; sha256sum "$LAUNCH"
echo "DEVICE BACKUP: $BACK"
REMOTE_INSTALL

echo "[10/10] SOURCE-ISOLATION PROOF"
docker exec -i "$CONTAINER" bash -s -- "$BASE" "$FORK" <<'DOCKER_PROOF'
BASE="$1"; FORK="$2"
echo "===== CURRENT TSP BASE (READ ONLY) ====="
sha256sum "$BASE/src/gl/framebuffers.c" "$BASE/src/gl/texture_params.c"

echo "===== TSPS BASE (UNTOUCHED) ====="
sha256sum /root/gl4es-tsps/src/gl/framebuffers.c /root/gl4es-tsps/src/gl/texture_params.c

echo "===== NEW TSP FORK ====="
sha256sum "$FORK/src/gl/framebuffers.c" "$FORK/src/gl/texture_params.c"

echo "===== FORK MARKERS ====="
grep -n 'TSP_PVR_RB_LIFETIME_FIX_V1\|TSP_NATIVE_LIFE_DIAG_V1'     "$FORK/src/gl/framebuffers.c"     "$FORK/src/gl/texture_params.c"
DOCKER_PROOF

echo
echo "============================================================"
echo "READY"
echo "============================================================"
echo "Run: Morrowind-TSP-PVR-LIFETIME-DIAG-V11.sh"
echo "TSP source fork: $FORK"
echo "TSP device lib:  $ROOT/lib.tsp-pvr-lifetime-v1/libGL.so.1"
echo "TSPS device lib: $ROOT/lib/libGL.so.1  (unchanged)"
echo "Diagnostic switch in V11: TSP_NATIVE_LIFE_DIAG=1 or 0"
echo "VM lib copy:     $LOCAL_GL"
echo "VM launcher:     $LOCAL_LAUNCHER"
